import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const u=JSON.parse('{"title":"巽下艮上 蛊：","description":"京氏易传 - 巽下艮上 蛊：","frontmatter":{"title":"巽下艮上 蛊：","description":"京氏易传 - 巽下艮上 蛊："},"headers":[],"relativePath":"zh/classics/jingshi/049.md","filePath":"zh/classics/jingshi/049.md"}'),i={name:"zh/classics/jingshi/049.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"巽下艮上-蛊",tabindex:"-1"},[l("巽下艮上 蛊： "),e("a",{class:"header-anchor",href:"#巽下艮上-蛊","aria-label":"Permalink to “巽下艮上 蛊：”"},"​")],-1),e("p",null,"适六爻，阴阳上下，本道存也。气运周而复始。山下见风，止而顺；内互悦而动。《易》云：“蛊者，事也”。（虎易注：“蛊者，事也”。语出序卦传。）先甲后甲，事分而令行。金土合木象，复本曰归魂。与震为飞伏。【辛酉金，庚辰土。】九三归魂立三公在世，应上九见宗庙。",-1),e("p",null,"建始庚戌至乙卯，【寒露，春分。】积算起乙卯至庚寅，（虎易注：庚寅疑为甲寅之误。）周而复始。土木入艮巽。【土木分艮巽宫。】",-1),e("p",null,"五星从位起太阴，【太阴水星入卦用。】危宿从位降辛酉金，【二十八宿，危宿入巽归魂山风蛊，九三辛酉金位上。】分气候二十八。【起积算数二十八，卦宫定吉凶。】",-1),e("p",null,"木上见土，风落山，贞，干于父事。阴阳复位，长幼分焉。八卦循环，始于巽，归魂内象见还元。六爻进退，吉凶在于四时。积算起宫，从乎建始。【卦用及身也。】",-1),e("p",null,"升阴阳，巽宫适变入离，文柔分矣。阴入阳退，见中虚，次水中女。（虎易注：“水”字疑为“入”或者“降”字之误。）八卦相荡，阴阳定位，迁入离宫八卦，纯火，以日用事。",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
